        );
CREATE TABLE rescan_proposals (
            proposal_id INTEGER PRIMARY KEY AUTOINCREMENT,
            job_id TEXT NOT NULL,
            target_detection_id INTEGER,
            image_filename TEXT NOT NULL,
            suggested_species TEXT,
