CREATE INDEX idx_images_timestamp ON images(timestamp DESC);
CREATE INDEX idx_detections_filename ON detections(image_filename);
CREATE INDEX idx_classifications_detection_id ON classifications(detection_id);
CREATE UNIQUE INDEX idx_classifications_detection_rank ON classifications(detection_id, rank);
CREATE INDEX idx_detections_status_filename ON detections(status, image_filename);
CREATE INDEX idx_detections_score ON detections(score DESC);
CREATE INDEX idx_detections_gallery_state_filename
        ON detections(status, lower(COALESCE(decision_state, '')), image_filename);
CREATE INDEX idx_detections_gallery_state_score
        ON detections(status, lower(COALESCE(decision_state, '')), score DESC);
CREATE INDEX idx_detections_created_at_desc
        ON detections(created_at DESC);
CREATE INDEX idx_images_review_status_timestamp ON images(review_status, timestamp);
CREATE INDEX idx_images_ptz_origin
        ON images(ptz_origin) WHERE ptz_origin IS NOT NULL;
CREATE INDEX idx_weather_ts ON weather_logs(timestamp DESC);
CREATE INDEX idx_inbox_ingest_events_created_at ON inbox_ingest_events(created_at DESC);
CREATE INDEX idx_inbox_ingest_events_status ON inbox_ingest_events(status);
CREATE INDEX idx_inbox_ingest_events_hash ON inbox_ingest_events(content_hash);
CREATE INDEX idx_rescan_proposals_job_id ON rescan_proposals(job_id);
CREATE INDEX idx_rescan_proposals_status ON rescan_proposals(status);
CREATE INDEX idx_reject_audit_created_at ON reject_audit(created_at DESC);
CREATE INDEX idx_reject_audit_raw_species ON reject_audit(raw_species_name);
CREATE INDEX idx_reject_audit_bbox ON reject_audit(bbox_x, bbox_y);
CREATE INDEX idx_manual_objects_image_status
        ON manual_objects(image_filename, status);
CREATE UNIQUE INDEX idx_label_subjects_image_unique
        ON label_subjects(image_filename)
        WHERE scope = 'image';
CREATE UNIQUE INDEX idx_label_subjects_detection_unique
        ON label_subjects(detection_id)
        WHERE scope = 'object';
CREATE TRIGGER trg_label_subject_object_matches_image
        BEFORE INSERT ON label_subjects
        WHEN NEW.scope = 'object'
         AND NOT EXISTS (
             SELECT 1
             FROM detections d
             WHERE d.detection_id = NEW.detection_id
               AND d.image_filename = NEW.image_filename
         )
        BEGIN
            SELECT RAISE(ABORT, 'object subject does not match detection image');
        END;
CREATE UNIQUE INDEX idx_human_label_facts_root_unique
        ON human_label_facts(subject_id, fact_type)
        WHERE supersedes_fact_id IS NULL;
CREATE UNIQUE INDEX idx_human_label_facts_successor_unique
        ON human_label_facts(supersedes_fact_id)
        WHERE supersedes_fact_id IS NOT NULL;
CREATE INDEX idx_human_label_facts_subject_type
        ON human_label_facts(subject_id, fact_type, fact_id);
CREATE TRIGGER trg_human_label_fact_scope
        BEFORE INSERT ON human_label_facts
        WHEN NOT EXISTS (
            SELECT 1
            FROM label_subjects s
            WHERE s.subject_id = NEW.subject_id
              AND (
                  (s.scope = 'image' AND NEW.fact_type IN (
                      'bird_presence', 'detector_miss'
                  ))
                  OR
                  (s.scope = 'object' AND NEW.fact_type IN (
                      'bird_presence', 'bbox_quality',
                      'bbox_correction', 'species_identity'
                  ))
              )
        )
        BEGIN
            SELECT RAISE(ABORT, 'fact type is invalid for subject scope');
        END;
CREATE TRIGGER trg_human_label_fact_supersession_axis
        BEFORE INSERT ON human_label_facts
        WHEN NEW.supersedes_fact_id IS NOT NULL
         AND NOT EXISTS (
             SELECT 1
             FROM human_label_facts previous
             WHERE previous.fact_id = NEW.supersedes_fact_id
               AND previous.subject_id = NEW.subject_id
               AND previous.fact_type = NEW.fact_type
         )
        BEGIN
            SELECT RAISE(ABORT, 'superseded fact belongs to another axis');
        END;
CREATE VIEW current_human_label_facts AS
        SELECT
            f.fact_id,
            f.schema_version,
            f.subject_id,
            s.scope,
            s.image_filename,
            s.detection_id,
            f.fact_type,
            f.assertion_state,
            f.answer_value,
            f.species_key,
            f.bbox_x,
            f.bbox_y,
            f.bbox_w,
            f.bbox_h,
            f.coordinate_space,
            f.context,
            f.source_kind,
            f.source_ref,
            f.installation_id,
            f.app_version,
            f.created_at,
            f.supersedes_fact_id,
            s.proposal_bbox_x,
            s.proposal_bbox_y,
            s.proposal_bbox_w,
            s.proposal_bbox_h,
            s.proposal_coordinate_space,
            s.proposal_species_key,
            s.detector_model_version,
            s.classifier_model_version
        FROM human_label_facts f
        JOIN label_subjects s ON s.subject_id = f.subject_id
        WHERE f.assertion_state = 'asserted'
          AND NOT EXISTS (
              SELECT 1
              FROM human_label_facts successor
              WHERE successor.supersedes_fact_id = f.fact_id
          );
CREATE INDEX idx_station_event_review_members_detection
        ON station_event_review_members(detection_id, review_id DESC);
CREATE INDEX idx_station_event_reviews_created
        ON station_event_reviews(created_at DESC);
CREATE INDEX idx_station_runtime_samples_time
        ON station_runtime_samples(sampled_at ASC);
DELETE FROM "sqlite_sequence";
INSERT INTO "sqlite_sequence" VALUES('sources',1);
INSERT INTO "sqlite_sequence" VALUES('detections',18);
INSERT INTO "sqlite_sequence" VALUES('classifications',18);
INSERT INTO "sqlite_sequence" VALUES('label_subjects',15);
INSERT INTO "sqlite_sequence" VALUES('human_label_facts',24);
INSERT INTO "sqlite_sequence" VALUES('manual_objects',2);
INSERT INTO "sqlite_sequence" VALUES('manual_object_revisions',2);
